-- Partner referral codes: a business shares www.byebyedoody.com/?ref=CODE; new customers get $10 off
-- (credit comes off ByeByeDoody's fee). Partners have no account; signups are counted here.
CREATE TABLE IF NOT EXISTS partner_codes (code TEXT PRIMARY KEY, business_name TEXT NOT NULL, segment TEXT, active INTEGER NOT NULL DEFAULT 1, signups INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
